-- 14) knowledge_doc（10 篇）
INSERT INTO knowledge_doc (id, title, doc_type, source_type, content, file_path, chunk_count, vector_status, status, create_time, update_time, deleted) VALUES
(1, '香格里拉十月出行注意事项', 'GUIDE', 'MANUAL', '香格里拉十月已进入深秋，日均气温 3℃ 至 15℃，昼夜温差大，建议携带羽绒服与保暖内衣。高原紫外线强烈，需备防晒霜与墨镜。普达措国家公园十月中旬进入最佳观赏期，湖水湛蓝，草甸金黄。前往梅里雪山需提前查询道路通行情况，连续降雨可能导致部分路段封闭。松赞林寺参观需脱帽、肃静，尊重藏传佛教习俗。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(2, '大理洱海环湖骑行全攻略', 'GUIDE', 'MANUAL', '洱海环湖全程约 120 公里，骑行建议分 2 天完成。西岸路况平缓，适合新手，可途经喜洲古镇、海舌公园；东岸坡多但风景更开阔，可看双廊日落。沿途补给点较多，租车价格 40-80 元/天。上午出发避开正午暴晒，骑行务必佩戴头盔并注意防晒。十月起湖边风大，体力消耗明显增加。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(3, '云南-昆明-景点-滇池', 'DESTINATION', 'MANUAL', '滇池是云南最大的淡水湖，有「高原明珠」之称。海埂公园是观赏滇池与西山全景的最佳位置，冬季可近距离观察红嘴鸥。环湖路适合骑行与散步，全长约 100 公里。周边配套餐饮完善，推荐品尝过桥米线与烤乳扇。景区免费开放，旺季（11月-次年3月）在翠湖公园亦可观赏海鸥。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(4, '云南-大理-景点-崇圣寺三塔', 'DESTINATION', 'MANUAL', '崇圣寺三塔始建于南诏国时期，是大理的地标建筑。主塔千寻塔高 69.13 米，历经千年地震仍屹立不倒。景区内可参观南诏建极大钟与雨铜观音殿，三塔倒影池是最佳拍照点。门票 75 元，开放时间 7:30-18:30，建议游玩 2 小时。龙王庙方向拍摄三塔与苍山同框效果最佳。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(5, '云南-丽江-景点-玉龙雪山', 'DESTINATION', 'MANUAL', '玉龙雪山是北半球最近赤道的雪山，主峰扇子陡海拔 5596 米。乘冰川大索道可达 4506 米观景台，需提前 1-3 天预订索道票。山下蓝月谷湖水呈翡翠色，被誉为「小九寨沟」。高原反应预防：建议提前一周服用红景天，山上减少剧烈运动。氧气瓶景区售价 60 元左右，山脚便利店更便宜。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(6, '海南-三亚-景点-蜈支洲岛', 'DESTINATION', 'MANUAL', '蜈支洲岛被誉为「中国的马尔代夫」，距三亚市区约 1 小时船程。岛上水质清澈，是海南最负盛名的潜水胜地，潜水分浮潜与深潜，价格 380-880 元不等。环岛电瓶车 120 元/人，可停靠多个观景台。冬季（11月-次年3月）水温适宜，是潜水最佳季节。岛上餐饮价格较高，建议自带零食。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(7, '湖南-张家界-景点-天门山', 'DESTINATION', 'MANUAL', '天门山因 1999 年飞机穿越天门洞而闻名。山顶玻璃栈道全长 60 米，悬于 1430 米峭壁之上。登顶需乘世界最长高山客运索道（7455 米），单程约 28 分钟。冬季可能出现雾凇景观，能见度低时索道可能停运。建议网上提前购票并关注景区公告，天门洞 999 级台阶体力消耗较大。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(8, '广西-桂林-景点-漓江', 'DESTINATION', 'MANUAL', '漓江桂林至阳朔段是最经典的山水画卷，全程83公里，乘竹筏游览精华段（杨堤-兴坪）约2.5小时。20元人民币背面图案取自兴坪古镇附近的漓江段。雨季水位上涨时竹筏可能停航，出发前建议查询漓江景区公告。阳朔西街夜晚热闹，推荐啤酒鱼与桂林米粉。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(9, '陕西-西安-景点-兵马俑', 'DESTINATION', 'MANUAL', '秦始皇帝陵博物院（兵马俑）是世界第八大奇迹，一号坑是目前发掘面积最大、兵马俑数量最多的坑。建议参观顺序：一号坑→三号坑→二号坑，全程约 2.5 小时。强烈建议租讲解器（30 元）或请讲解员，否则难以理解坑道布局与文物细节。门票 120 元，需提前 1-7 天实名预约。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0),
(10, '四川-成都-熊猫基地', 'DESTINATION', 'MANUAL', '成都大熊猫繁育研究基地是观赏大熊猫的最佳去处。大熊猫活跃时段为清晨（8:30-10:00），建议开门即入园。月亮产房可近距离观看幼崽，成年大熊猫在太阳产房与熊猫别墅。园区电瓶车 10 元/人，可直达月亮产房。全程步行约 3 小时，请勿投喂与大声喧哗。门票 55 元，需提前预约。', '', 0, 0, 1, '2026-08-10 00:00:00', '2026-08-10 00:00:00', 0);

