-- 16) ai_insight（近 2 天）
INSERT INTO ai_insight (id, insight_date, content, highlights_json, model, generated_at, create_time, update_time) VALUES
(1, '2026-09-18', '昨日平台预约量环比上升 12.4%，主要由「云南大理丽江香格里拉 5 日纯玩」带动（+28.6%），其中华东地区用户贡献 43%。评论情感正面率 74.1%，负面关键词集中在「行程赶」（38 次）与「住宿差」（21 次）。建议优先核查 4 条 5 日以上线路的单日景点数量，并针对华东用户加大云南线路首页曝光。', '[{"type":"growth","text":"预约量环比 +12.4%"},{"type":"warning","text":"负面关键词「行程赶」38 次"},{"type":"suggestion","text":"核查 5 日以上线路单日景点数"}]', 'deepseek-chat', '2026-09-18 02:10:33', '2026-09-18 02:10:33', '2026-09-18 02:10:33'),
(2, '2026-09-17', '本周平台预约量平稳，三亚亲子线路热度持续攀升（+15.2%），可能与寒暑假亲子出游需求相关。用户地域分布集中在广东（18%）与浙江（14%）。负面反馈中「购物点过多」出现 12 次，建议核查部分线路的购物点占比，评估是否压缩购物行程。', '[{"type":"growth","text":"三亚亲子线路热度 +15.2%"},{"type":"warning","text":"「购物点过多」反馈 12 次"},{"type":"suggestion","text":"评估压缩购物行程"}]', 'deepseek-chat', '2026-09-17 02:15:40', '2026-09-17 02:15:40', '2026-09-17 02:15:40');


-- ============================================================
-- 17) 冗余列同步（第 2 批验收发现：route 冗余列初始为 0，与互动明细表不同步）
--     重跑本脚本后必须执行此段，否则列表/详情计数显示偏低。
-- ============================================================
UPDATE route r
SET r.like_count = (SELECT COUNT(*) FROM route_like rl WHERE rl.route_id = r.id),
    r.favorite_count = (SELECT COUNT(*) FROM route_favorite rf WHERE rf.route_id = r.id),
    r.comment_count = (SELECT COUNT(*) FROM route_comment rc WHERE rc.route_id = r.id AND rc.deleted = 0),
    r.booking_count = (SELECT COUNT(*) FROM route_booking rb WHERE rb.route_id = r.id AND rb.status IN (0,1,3)),
    r.avg_score = COALESCE((SELECT AVG(rc.score) FROM route_comment rc
                            WHERE rc.route_id = r.id AND rc.deleted = 0 AND rc.status = 1), r.avg_score);
